#include <vector>
#include <iostream>

int main() {
    std::vector<int> v1 = {1, 2, 3};  // Contiguous memory layout
    std::vector<int> v2 = {1, 2, 4};  // Elements stored sequentially
    bool result = (v1 < v2);  // Triggers lexicographical comparison
    std::cout << "v1 < v2: " << result << std::endl;  // Outputs: 1 (true)
    return 0;
}
